package com.pridesys.ticketing.client.controller;import com.pridesys.ticketing.client.service.IClientService;import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.UserEntity;import com.pridesys.ticketing.repository.UserRepository;import com.pridesys.ticketing.security.util.JwtService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;
@RestController@RequestMapping("/api/clients")public class ClientController{private final UserRepository users;private final IClientService service;public ClientController(UserRepository u,IClientService s){users=u;service=s;}private UserEntity actor(Authentication a){return users.findById(((JwtService.UserPrincipal)a.getPrincipal()).id()).orElseThrow();}@GetMapping public List<ClientResponseDto> list(Authentication a){return service.list(actor(a));}@PostMapping public ClientResponseDto create(Authentication a,@Valid@RequestBody UsersProjectsDtos.CreateClientRequest r){return service.create(actor(a),r);}}
